<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><h1>Leads</h1><div class="row"><?php foreach (['open' => 'Open', 'overdue' => 'Follow-up overdue', 'converted' => 'Converted', 'all' => 'All'] as $k => $l): ?><a class="btn btn-sm <?= $f === $k ? 'btn-dark' : 'btn-ghost' ?>" href="?f=<?= $k ?>"><?= $l ?></a><?php endforeach; ?></div></div>
<div class="kpis"><div class="kpi"><div class="l">Leads (30d)</div><div class="v"><?= (int)$m['leads'] ?></div></div><div class="kpi"><div class="l">Converted</div><div class="v"><?= (int)$m['leads_converted'] ?></div></div><div class="kpi"><div class="l">Conversion</div><div class="v"><?= e($m['conversion_rate']) ?></div></div><div class="kpi"><div class="l">Pipeline value</div><div class="v"><?= e($m['pipeline_value']) ?></div></div><div class="kpi<?= $m['leads_overdue'] ? ' warn' : '' ?>"><div class="l">Overdue follow-ups</div><div class="v"><?= (int)$m['leads_overdue'] ?></div></div></div>
<?php if ($m['lead_sources']): ?><p class="small muted">Sources: <?php foreach ($m['lead_sources'] as $s): ?><span class="badge"><?= e($s['source']) ?> <?= (int)$s['n'] ?></span> <?php endforeach; ?></p><?php endif; ?>
<?php if (!$rows): ?><div class="empty">No leads in this view.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Lead</th><th>Need</th><th>Score</th><th>Value</th><th>Source</th><th>Status</th><th>Next follow-up</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $l): ?><tr><td><a href="/admin/customers/<?= (int)$l['customer_id'] ?>"><b><?= e($l['name'] ?: $l['email']) ?></b></a><div class="small muted"><?= e($l['business_name']) ?> <?= e($l['email']) ?></div></td><td class="small"><?= e(str_limit((string)$l['summary'], 90)) ?></td>
  <td><span class="badge <?= $l['score'] >= 60 ? 'b-green' : ($l['score'] >= 35 ? 'b-blue' : '') ?>"><?= (int)$l['score'] ?></span></td><td><?= money((int)$l['estimated_value_cents']) ?></td><td class="small"><?= e($l['source']) ?></td><td><?php $badge($l['status']); ?></td><td class="small"><?= e(substr((string)$l['next_follow_up_at'], 0, 10)) ?><?= $l['opted_out'] ? ' <span class="badge b-red">opted out</span>' : '' ?> (<?= (int)$l['follow_up_count'] ?> sent)</td>
  <td><form method="post" action="/admin/leads/<?= (int)$l['id'] ?>" class="row"><?= App\Csrf::field() ?><select name="status" style="width:auto;padding:6px"><?php foreach (['lead', 'qualified', 'proposal_sent', 'awaiting_decision', 'converted', 'closed'] as $s): ?><option<?= $l['status'] === $s ? ' selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn btn-ghost btn-sm">Set</button></form></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
